def edit_distance(word_a, word_b):
    n = len(word_a)
    m = len(word_b)
    # Create a 2D array to store the edit distances
    edit = [[0 for _ in range(m+1)] for _ in range(n+1)]

    # Initialize the base cases
    for i in range(n+1):
        edit[i][0] = i
    for j in range(m+1):
        edit[0][j] = j

    # Fill the matrix using the Levenshtein distance formula
    for i in range(1, n+1):
        for j in range(1, m+1):
            if word_a[i-1] == word_b[j-1]:
                cost = 0
            else:
                cost = 1
            edit[i][j] = min(edit[i-1][j] + 1, edit[i][j-1] + 1, edit[i-1][j-1] + cost)

    # The bottom right cell contains the edit distance between word_a and word_b
    return edit[n][m]
