def edit_distance(word_a, word_b):
    # Initialize the length of the strings
    n, m = len(word_a), len(word_b)

    # Create a matrix to store the edit distances
    edit = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Base case: edit distance of empty string to any string is the length of the string
    for i in range(n + 1):
        edit[i][0] = i
    for j in range(m + 1):
        edit[0][j] = j

    # Fill the matrix using the edit distance formula
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if word_a[i - 1] == word_b[j - 1]:
                cost = 0
            else:
                cost = 1
            # Calculate the minimum cost by considering deletion, insertion, and substitution
            edit[i][j] = min(edit[i - 1][j] + 1, edit[i][j - 1] + 1, edit[i - 1][j - 1] + cost)

    # The answer is in the bottom-right corner of the matrix
    return edit[n][m]
