def find_pairs(numbers, target_sum):
    seen = {}
    pairs = set()

    for number in numbers:
        complement = target_sum - number
        if complement in seen:
            pairs.add((min(number, complement), max(number, complement)))
        seen[number] = True

    return sorted(list(pairs))

